"use client";
import { useSyncExternalStore } from "react";
const hasWindow = () => typeof window !== "undefined";
const CHAT_NAVIGATED_EVENT = "ai-matrx-chat:navigated";
function subscribeToHistory(listener) {
  if (!hasWindow()) return () => {
  };
  window.addEventListener("popstate", listener);
  window.addEventListener(CHAT_NAVIGATED_EVENT, listener);
  return () => {
    window.removeEventListener("popstate", listener);
    window.removeEventListener(CHAT_NAVIGATED_EVENT, listener);
  };
}
function useWindowPathname() {
  return useSyncExternalStore(
    subscribeToHistory,
    () => window.location.pathname,
    () => "/"
  );
}
let lastSearch = null;
let lastParams = new URLSearchParams();
function paramsFor(search) {
  if (search !== lastSearch) {
    lastSearch = search;
    lastParams = new URLSearchParams(search);
  }
  return lastParams;
}
function useWindowSearchParams() {
  const search = useSyncExternalStore(
    subscribeToHistory,
    () => window.location.search,
    () => ""
  );
  return paramsFor(search);
}
export {
  CHAT_NAVIGATED_EVENT,
  useWindowPathname,
  useWindowSearchParams
};
