function createDbFeedback(db, identity) {
  return {
    async submit(input) {
      const person = identity().current();
      if (!person.isAuthenticated || !person.userId) {
        return { success: false, error: "User not authenticated" };
      }
      const organizationId = input.organization_id?.trim() ?? "";
      if (!organizationId) {
        return {
          success: false,
          error: "Select an organization before sending feedback \u2014 every report is filed under one organization."
        };
      }
      const { data, error } = await db.schema("users").from("user_feedback").insert({
        organization_id: organizationId,
        user_id: person.userId,
        created_by: person.userId,
        username: person.email ?? person.displayName ?? "Anonymous",
        feedback_type: input.feedback_type,
        route: input.route,
        description: input.description,
        image_file_ids: input.image_file_ids ?? [],
        status: "new",
        metadata: input.metadata ?? {}
      }).select("id").single();
      if (error) return { success: false, error: error.message };
      const id = data?.id;
      return typeof id === "string" ? { success: true, data: { id } } : { success: false, error: "no row came back" };
    }
  };
}
export {
  createDbFeedback
};
