const DEFAULT_CHAT_SERVER_URL = "https://server.app.matrxserver.com";
function createDefaultServer(identity, org) {
  return {
    baseUrl: () => DEFAULT_CHAT_SERVER_URL,
    async headers() {
      const headers = {};
      const token = await identity().getAccessToken();
      if (token) headers.Authorization = `Bearer ${token}`;
      const active = org().active();
      if (active) headers["X-Organization-Id"] = active.id;
      return headers;
    }
  };
}
export {
  DEFAULT_CHAT_SERVER_URL,
  createDefaultServer
};
